<script setup lang="ts">
import {computed,onMounted,reactive,ref,watch} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {Search,RotateCcw,Plus,Pencil,Power,History,Trash2,Package,ShieldCheck,Clock3,ArrowUpRight} from 'lucide-vue-next'
import {request,send} from './api'
import RichEditor from './RichEditor.vue'
import ProductDocument from './ProductDocument.vue'
import CoverImagePicker from './CoverImagePicker.vue'
import RecordIdentifier from './RecordIdentifier.vue'
const rows=ref<any[]>([]),exams=ref<any[]>([]),cycles=ref<any[]>([]),busy=ref(false),working=ref(false),error=ref(''),page=ref(1)
const filters=reactive({search:'',type:'',examId:'',cycleId:'',level:'',state:''})
const stateNames:Record<string,string>={draft:'草稿',selling:'销售中',scheduled:'待考期开启',offline:'已下架',expired:'考期已结束',unavailable:'考试已停用'}
const typeNames:Record<string,string>={entitlement:'权益商品',trial:'体验权益'}
const matches=computed(()=>rows.value.filter(r=>(!filters.search||[r.title,r.frontend_title].some(name=>name?.includes(filters.search.trim())))&&(!filters.type||r.type===filters.type)&&(!filters.examId||r.exam_id===filters.examId)&&(!filters.cycleId||r.cycle_id===filters.cycleId)&&(!filters.level||r.level===filters.level)&&(!filters.state||r.saleState===filters.state)))
const items=computed(()=>matches.value.slice((page.value-1)*20,page.value*20))
const counts=computed(()=>[{label:'全部商品',value:rows.value.length,icon:Package},{label:'销售中',value:rows.value.filter(r=>r.saleState==='selling').length,icon:ShieldCheck},{label:'体验权益',value:rows.value.filter(r=>r.type==='trial').length,icon:Clock3}])
const money=(n:number)=>'¥'+(n/100).toFixed(2),date=(s:string)=>s?new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'—'
let loadVersion=0
async function load(){const v=++loadVersion;busy.value=true;error.value='';try{const [p,e,c]=await Promise.all([request('/admin/products'),request('/admin/exam-projects'),request('/admin/exams')]);if(v===loadVersion){rows.value=p;exams.value=e;cycles.value=c}}catch(e:any){error.value=e.message}finally{if(v===loadVersion)busy.value=false}}
function reset(){Object.assign(filters,{search:'',type:'',examId:'',cycleId:'',level:'',state:''});page.value=1}
watch(filters,()=>page.value=1)
watch(()=>filters.examId,()=>filters.cycleId='')
const drawer=ref(false),draft=ref<any>({}),editingId=ref(''),version=ref(0),locked=ref(false),tab=ref('basic'),formError=ref(''),coverBusy=ref(false),bodyBusy=ref(false)
const blocked=computed(()=>working.value||coverBusy.value||bodyBusy.value)
const price=ref<number|null>(null),original=ref<number|null>(null)
watch([draft,price,original],()=>{formError.value=''},{deep:true})
const periodOptions=computed(()=>cycles.value.filter(c=>c.exam_id===draft.value.examId))
const selectedPeriod=computed(()=>periodOptions.value.find(c=>c.id===draft.value.cycleId))
const permissions=ref<any>(null)
const benefits=computed(()=>permissions.value?.catalog.filter((p:any)=>permissions.value.policies.find((p:any)=>p.level===draft.value.level)?.permissions[p.key]).map((p:any)=>p.name)||[])
let permissionRevision=0
watch(()=>draft.value.examId,async examId=>{const v=++permissionRevision;permissions.value=null;if(examId)try{const data=await request('/admin/permission-policies/'+examId);if(v===permissionRevision)permissions.value=data}catch(e:any){if(v===permissionRevision)formError.value=e.message}})
function changeExam(){draft.value.cycleId=''}
function open(row?:any){if(blocked.value)return;editingId.value=row?.id||crypto.randomUUID();version.value=row?.version||0;locked.value=!!row?.has_paid;draft.value=row?JSON.parse(JSON.stringify(row.config)):{title:'',frontendTitle:'',type:'entitlement',examId:'',cycleId:'',level:'vip',priceCents:0,originalPriceCents:null,coverUrl:'',intro:'',document:null,status:'draft',sortOrder:0,trialHours:24,minimumHours:10,shortNotice:'当前考期剩余时间不足完整体验时长，本次实际可用 {{实际可用时长}}，至 {{考期结束时间}} 结束。请确认后支付。'};price.value=row?row.price_cents/100:null;original.value=row?.original_price_cents?row.original_price_cents/100:null;tab.value='basic';formError.value='';drawer.value=true}
function beforeClose(done:()=>void){if(!blocked.value)done()}
async function save(){if(blocked.value)return;formError.value='';
 if(!draft.value.frontendTitle?.trim()||!draft.value.title.trim()||!draft.value.examId||!draft.value.cycleId){tab.value='basic';formError.value='请填写前端商品名称、后台商品名称、所属考试和考期';return}
 if(price.value==null||price.value<=0){tab.value='rules';formError.value='请填写大于 0 的售价';return}
 if(draft.value.type==='trial'&&(!draft.value.trialHours||!draft.value.minimumHours||!draft.value.shortNotice.trim()||draft.value.minimumHours>draft.value.trialHours)){tab.value='rules';formError.value='请填写体验时长、最低时长和提示语；最低时长不能大于体验时长';return}
 working.value=true;try{await send('/admin/products/'+editingId.value,{version:version.value,config:{...draft.value,priceCents:Math.round(price.value*100),originalPriceCents:original.value==null?null:Math.round(original.value*100)}},'PUT');drawer.value=false;await load();ElMessage.success('商品已保存，历史版本已记录')}catch(e:any){formError.value=e.message}finally{working.value=false}}
async function status(row:any){if(working.value)return;const publish=row.status!=='published';try{await ElMessageBox.confirm(publish?'上架后将按考期开始、结束时间自动控制购买。':'下架后新用户和待支付订单均不能付款，已购权益不受影响。',publish?'上架商品':'下架商品',{confirmButtonText:'确认',cancelButtonText:'取消',type:'warning'});working.value=true;await send('/admin/products/'+row.id+'/status',{version:row.version,status:publish?'published':'offline'},'PATCH');await load();ElMessage.success('状态已更新并保存版本')}catch(e:any){if(e?.message)ElMessage.error(e.message)}finally{working.value=false}}
async function remove(row:any){try{await ElMessageBox.confirm(`删除“${row.title}”及其历史版本？此操作无法撤销。`,'删除商品',{type:'warning',confirmButtonText:'删除',cancelButtonText:'取消'});working.value=true;await send('/admin/products/'+row.id,{version:row.version},'DELETE');await load()}catch(e:any){if(e?.message)ElMessage.error(e.message)}finally{working.value=false}}
const historyOpen=ref(false),historyRows=ref<any[]>([]),historyProduct=ref<any>(),selectedHistory=ref<any>(),historyBusy=ref(false)
async function history(row:any){historyProduct.value=row;historyOpen.value=true;historyBusy.value=true;selectedHistory.value=null;try{historyRows.value=await request('/admin/products/'+row.id+'/versions');selectedHistory.value=historyRows.value[0]}catch(e:any){ElMessage.error(e.message)}finally{historyBusy.value=false}}
const previewHtml=computed(()=>selectedHistory.value?.html||'')
async function restore(){const old=selectedHistory.value;if(!old||working.value)return;try{await ElMessageBox.confirm(`将版本 V${old.version} 的内容和上下架设置恢复为新的当前版本。历史记录不会被覆盖，已支付订单不受影响。`,'恢复历史版本',{confirmButtonText:'恢复此版本',cancelButtonText:'取消',type:'warning'});working.value=true;await send('/admin/products/'+historyProduct.value.id+'/restore',{version:historyProduct.value.version,sourceVersion:old.version});await load();await history(rows.value.find(p=>p.id===historyProduct.value.id));ElMessage.success('历史版本已恢复，并生成新版本')}catch(e:any){if(e?.message)ElMessage.error(e.message)}finally{working.value=false}}
onMounted(load);defineExpose({load,open})
</script>

<template>
 <section class="products-page">
  <div class="product-metrics"><article v-for="metric in counts" :key="metric.label"><div class="metric-symbol"><component :is="metric.icon" :size="22" aria-hidden="true"/></div><div><span>{{metric.label}}</span><strong>{{metric.value}}</strong></div></article></div>
  <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/>
  <form class="admin-filters" @submit.prevent="page=1"><label class="admin-filter-field"><span>商品名称</span><el-input v-model="filters.search" clearable placeholder="搜索前端或后台商品名称" aria-label="筛选商品名称"><template #prefix><Search :size="16"/></template></el-input></label><label class="admin-filter-field"><span>商品类型</span><el-select v-model="filters.type" :empty-values="[null,undefined]" aria-label="筛选商品类型"><el-option label="全部类型" value=""/><el-option v-for="(label,key) in typeNames" :key="key" :value="key" :label="label"/></el-select></label><label class="admin-filter-field"><span>考试项目</span><el-select v-model="filters.examId" filterable :empty-values="[null,undefined]" aria-label="筛选考试"><el-option label="全部考试" value=""/><el-option v-for="e in exams" :key="e.id" :value="e.id" :label="e.name"/></el-select></label><label class="admin-filter-field"><span>考期</span><el-select v-model="filters.cycleId" :disabled="!filters.examId" :empty-values="[null,undefined]" aria-label="筛选考期"><el-option label="全部考期" value=""/><el-option v-for="c in cycles.filter(c=>c.exam_id===filters.examId)" :key="c.id" :value="c.id" :label="c.year+' 年考期'"/></el-select></label><label class="admin-filter-field"><span>权益档位</span><el-select v-model="filters.level" :empty-values="[null,undefined]" aria-label="筛选权益档位"><el-option label="全部档位" value=""/><el-option label="VIP" value="vip"/><el-option label="SVIP" value="svip"/></el-select></label><label class="admin-filter-field"><span>销售状态</span><el-select v-model="filters.state" :empty-values="[null,undefined]" aria-label="筛选销售状态"><el-option label="全部状态" value=""/><el-option v-for="(label,key) in stateNames" :key="key" :value="key" :label="label"/></el-select></label><div class="admin-filter-actions"><el-button type="primary" native-type="submit"><Search :size="16"/>查询</el-button><el-button @click="reset"><RotateCcw :size="16"/>重置</el-button></div></form>
  <div class="table-toolbar"><span>商品列表 <b>{{matches.length}}</b></span><span class="product-help">每次保存保留版本，已购权益独立生效</span></div>
  <el-table v-loading="busy" :data="items" row-key="id"><template #empty><el-empty description="暂无商品，创建你的第一款权益商品" :image-size="85"/></template>
   <el-table-column label="商品" min-width="265"><template #default="{row}"><div class="product-cell"><img v-if="row.cover_url" :src="row.cover_url" alt="商品封面"/><div v-else class="product-cover"><Package :size="24"/></div><div><button class="table-title" @click="open(row)">{{row.title}}</button><small class="cell-sub">{{typeNames[row.type]}} · {{row.level.toUpperCase()}}{{row.type==='trial'?' · '+row.trial_hours+' 小时':''}}</small></div></div></template></el-table-column>
   <el-table-column label="考试 / 考期" min-width="180"><template #default="{row}">{{row.exam_name}}<small class="cell-sub">{{row.year}} 年考期</small></template></el-table-column>
   <el-table-column label="售价" width="120"><template #default="{row}"><strong class="product-price">{{money(row.price_cents)}}</strong></template></el-table-column>
   <el-table-column label="销售状态" width="125"><template #default="{row}"><el-tag :type="row.saleState==='selling'?'success':row.saleState==='scheduled'?'warning':'info'" effect="plain">{{stateNames[row.saleState]}}</el-tag></template></el-table-column>
   <el-table-column label="当前版本" width="100"><template #default="{row}"><button class="version-link" @click="history(row)">V{{row.version}}</button></template></el-table-column>
   <el-table-column label="更新时间" min-width="170"><template #default="{row}">{{date(row.updated_at)}}</template></el-table-column>
   <el-table-column label="操作" width="160" fixed="right"><template #default="{row}"><div class="row-actions"><el-tooltip content="编辑商品"><el-button link type="primary" aria-label="编辑商品" :disabled="working" @click="open(row)"><Pencil :size="17"/></el-button></el-tooltip><el-tooltip :content="row.status==='published'?'下架':'上架'"><el-button link :type="row.status==='published'?'danger':'success'" :aria-label="row.status==='published'?'下架商品':'上架商品'" :disabled="working||row.saleState==='expired'" @click="status(row)"><Power :size="17"/></el-button></el-tooltip><el-tooltip content="历史版本"><el-button link type="primary" aria-label="历史版本" @click="history(row)"><History :size="17"/></el-button></el-tooltip><el-tooltip :content="row.has_orders?'已有订单，仅可下架':'删除商品'"><span><el-button link type="danger" aria-label="删除商品" :disabled="row.has_orders||working" @click="remove(row)"><Trash2 :size="17"/></el-button></span></el-tooltip></div></template></el-table-column>
  </el-table><div class="pagination"><span>共 {{matches.length}} 条</span><el-pagination v-model:current-page="page" :page-size="20" :total="matches.length" layout="prev,pager,next"/></div>
 </section>
 <el-drawer v-model="drawer" :title="version?'编辑商品':'新增商品'" size="min(960px,100vw)" class="product-drawer" destroy-on-close :close-on-click-modal="false" :before-close="beforeClose">
  <template v-if="drawer"><RecordIdentifier v-if="version" :id="editingId" table="products"/><el-alert v-if="formError" :title="formError" type="error" :closable="false" show-icon/>
  <el-tabs v-model="tab" :before-leave="()=>!blocked"><el-tab-pane label="基本信息" name="basic"/><el-tab-pane label="售价与权益" name="rules"/><el-tab-pane label="商品详情" name="display"/></el-tabs>
  <div class="product-editor-layout"><el-form label-position="top" :disabled="working" class="product-form">
   <template v-if="tab==='basic'"><div class="form-section-title"><Package :size="18"/><strong>定义商品</strong></div><el-form-item label="前端商品名称" required><el-input v-model="draft.frontendTitle" maxlength="100" show-word-limit aria-label="前端商品名称" placeholder="例如：VIP 全考期学习套餐"/><small class="field-help">显示在商品概览和用户端商品、订单中。</small></el-form-item><el-form-item label="后台商品名称" required><el-input v-model="draft.title" maxlength="100" show-word-limit aria-label="后台商品名称" placeholder="例如：2027 初级社会工作师 VIP 套餐"/><small class="field-help">用于后台商品管理和订单管理，方便内部识别。</small></el-form-item><el-form-item label="商品类型" required><el-radio-group v-model="draft.type" :disabled="locked"><el-radio-button value="entitlement">权益商品</el-radio-button><el-radio-button value="trial">体验权益商品</el-radio-button></el-radio-group></el-form-item><el-form-item label="所属考试" required><el-select v-model="draft.examId" filterable :disabled="locked" aria-label="商品所属考试" placeholder="请选择考试" @change="changeExam"><el-option v-for="e in exams" :key="e.id" :value="e.id" :label="e.name"/></el-select></el-form-item><el-form-item label="适用考期" required><el-select v-model="draft.cycleId" :disabled="locked||!draft.examId" aria-label="商品适用考期" :placeholder="draft.examId?'请选择考期':'请先选择考试'"><el-option v-for="c in periodOptions" :key="c.id" :value="c.id" :label="c.year+' 年考期'"/></el-select><small v-if="selectedPeriod" class="field-help">{{date(selectedPeriod.starts_at)}} 至 {{date(selectedPeriod.ends_at)}}（北京时间）</small><small v-else-if="draft.examId&&!periodOptions.length" class="field-help">该考试尚未配置考期，请先在考试项目中添加。</small></el-form-item><div class="product-two-fields"><el-form-item label="上架设置"><el-select v-model="draft.status" aria-label="商品上架设置"><el-option label="草稿" value="draft"/><el-option label="上架" value="published"/><el-option label="下架" value="offline"/></el-select></el-form-item><el-form-item label="展示排序"><el-input-number v-model="draft.sortOrder" :min="0" :max="99999"/></el-form-item></div><p class="field-help">上架商品在考期开始后可购买，到期自动停止售卖。数字越小，展示越靠前。</p><el-alert v-if="locked" title="已有支付订单，商品类型、考试、考期及权益档位已锁定。" type="info" :closable="false"/></template>
   <template v-if="tab==='rules'"><div class="form-section-title"><ShieldCheck :size="18"/><strong>售价与权益发放</strong></div><div class="product-two-fields"><el-form-item label="售价（元）" required><el-input-number v-model="price" :min="0.01" :max="1000000" :precision="2" :controls="false" aria-label="商品售价"/></el-form-item><el-form-item label="划线原价（选填）"><el-input-number v-model="original" :min="0.01" :max="1000000" :precision="2" :controls="false" aria-label="商品原价"/></el-form-item></div><el-form-item label="关联权益档位" required><el-radio-group v-model="draft.level" :disabled="locked"><el-radio-button value="vip">VIP</el-radio-button><el-radio-button value="svip">SVIP</el-radio-button></el-radio-group></el-form-item><div class="benefit-preview"><strong>关联权益（仅后台参考）</strong><span v-if="!draft.examId">选择考试后显示对应权益</span><ul v-else><li v-for="name in benefits" :key="name">{{name}}</li></ul><a href="#permissions" @click="drawer=false">前往会员权益配置 <ArrowUpRight :size="14"/></a></div><template v-if="draft.type==='trial'"><div class="trial-fields"><h3><Clock3 :size="17"/>体验购买规则</h3><div class="product-two-fields"><el-form-item label="体验时长（小时）" required><el-input-number v-model="draft.trialHours" :min="0.01" :max="8760" :precision="2" aria-label="体验时长"/></el-form-item><el-form-item label="最低可购买时长（小时）" required><el-input-number v-model="draft.minimumHours" :min="0.01" :max="8760" :precision="2" aria-label="最低可购买时长"/></el-form-item></div><el-form-item label="支付确认提示语" required><el-input v-model="draft.shortNotice" type="textarea" :rows="4" maxlength="1000" show-word-limit aria-label="支付确认提示语"/></el-form-item><p class="field-help" v-pre>可用变量：{{实际可用时长}}、{{体验时长}}、{{考期结束时间}}。实际时长和结束时间会固定显示，不受文案修改影响。</p><div class="trial-rules"><span>剩余 ≥ {{draft.trialHours||'—'}} 小时：正常购买</span><span>{{draft.minimumHours||'—'}} ～ {{draft.trialHours||'—'}} 小时：支付前提醒确认</span><span>不足 {{draft.minimumHours||'—'}} 小时：禁止购买</span></div></div><p class="field-help">账号终身仅可体验一次，购买过正式权益后不能体验。支付后开始计时，最晚至考期结束。</p></template><p v-else class="field-help">支付成功后生效，至本考期结束。售价不会随剩余天数折算，同一考试考期内只能购买一次正式权益。</p></template>
   <template v-if="tab==='display'"><div class="form-section-title"><Pencil :size="18"/><strong>用户看到的商品内容</strong></div><el-form-item label="商品封面"><CoverImagePicker v-model="draft.coverUrl" :content-id="editingId" @busy="coverBusy=$event"/></el-form-item><el-form-item label="简短介绍"><el-input v-model="draft.intro" type="textarea" :rows="3" maxlength="500" show-word-limit/></el-form-item><el-form-item label="图文详情"><RichEditor v-model="draft.document" :content-id="editingId" :allow-media="false" :allow-handouts="false" @busy="bodyBusy=$event"/></el-form-item></template>
  </el-form><aside class="product-preview"><span class="preview-label">商品概览</span><img v-if="draft.coverUrl" :src="draft.coverUrl" alt="商品封面预览"/><div v-else class="preview-placeholder"><component :is="draft.type==='trial'?Clock3:ShieldCheck" :size="34"/></div><el-tag effect="plain">{{typeNames[draft.type]}}</el-tag><h2>{{draft.frontendTitle||'前端商品名称'}}</h2><p>{{draft.intro||'添加一段介绍，帮助用户了解这款商品。'}}</p><strong class="preview-price">{{money(Math.round((price||0)*100))}}</strong><del v-if="original" class="preview-original">{{money(Math.round(original*100))}}</del><span class="preview-term">{{selectedPeriod?selectedPeriod.year+' 年考期':'尚未选择考期'}} · {{draft.level?.toUpperCase()}}</span><section v-if="draft.document" class="preview-document"><strong>图文详情</strong><ProductDocument :document="draft.document"/></section></aside></div></template>
  <template #footer><span class="version-note">保存后生成 {{version?'V'+(version+1):'V1'}} 版本</span><el-button :disabled="blocked" @click="drawer=false">取消</el-button><el-button type="primary" :loading="working" :disabled="coverBusy||bodyBusy" @click="save">保存商品</el-button></template>
 </el-drawer>
 <el-drawer v-model="historyOpen" title="商品历史版本" size="min(850px,100vw)" class="product-history" :before-close="beforeClose"><div v-loading="historyBusy"><p class="history-heading">{{historyProduct?.title}}<el-tag>当前 V{{historyProduct?.version}}</el-tag></p><div class="history-layout"><nav aria-label="选择商品历史版本"><button v-for="h in historyRows" :key="h.version" :class="{selected:selectedHistory?.version===h.version}" @click="selectedHistory=h"><strong>V{{h.version}} <span>{{h.action.startsWith('restore')?'恢复版本':h.action==='publish'?'上架':h.action==='offline'?'下架':'保存'}}</span></strong><time>{{date(h.created_at)}}</time><small>{{h.actor_name||'管理员'}}</small></button></nav><article v-if="selectedHistory" class="history-preview"><h2>{{selectedHistory.snapshot.title}}</h2><el-descriptions :column="1" border><el-descriptions-item label="前端商品名称">{{selectedHistory.snapshot.frontendTitle||selectedHistory.snapshot.title}}</el-descriptions-item><el-descriptions-item label="后台商品名称">{{selectedHistory.snapshot.title}}</el-descriptions-item><el-descriptions-item label="商品类型">{{typeNames[selectedHistory.snapshot.type]}}</el-descriptions-item><el-descriptions-item label="考试">{{exams.find(e=>e.id===selectedHistory.snapshot.examId)?.name||selectedHistory.snapshot.examId}}</el-descriptions-item><el-descriptions-item label="考期">{{cycles.find(c=>c.id===selectedHistory.snapshot.cycleId)?.year||'已移除'}}</el-descriptions-item><el-descriptions-item label="权益">{{selectedHistory.snapshot.level.toUpperCase()}}</el-descriptions-item><el-descriptions-item label="售价 / 原价">{{money(selectedHistory.snapshot.priceCents)}} / {{selectedHistory.snapshot.originalPriceCents?money(selectedHistory.snapshot.originalPriceCents):'—'}}</el-descriptions-item><el-descriptions-item label="上架设置">{{({draft:'草稿',published:'上架',offline:'下架'} as any)[selectedHistory.snapshot.status]}}</el-descriptions-item><el-descriptions-item label="展示排序">{{selectedHistory.snapshot.sortOrder}}</el-descriptions-item><template v-if="selec